<script setup lang="ts">import { Link,useForm } from '@inertiajs/vue3';import { Plus,Trash2 } from '@lucide/vue';import { computed,watch } from 'vue';import { Button } from '@/components/ui/button';import { Input } from '@/components/ui/input';type Customer={id:string;person_id:string;name:string;default_price_list_id:string|null};type List={id:string;name:string;is_default:boolean;items:any[]};const props=defineProps<{customers:Customer[];priceLists:List[];orders:any[];accounts:any[];now:string}>();const defaultList=props.priceLists.find(l=>l.is_default)?.id??props.priceLists[0]?.id??'';const form=useForm({customer_profile_id:'',sales_order_id:'',price_list_id:defaultList,sold_at:props.now,due_at:'',discount:0,lines:[] as any[],payments:[] as any[]});const list=computed(()=>props.priceLists.find(l=>l.id===form.price_list_id));const total=computed(()=>Math.max(0,form.lines.reduce((s,l)=>s+Number(l.quantity||0)*Number(l.unit_price||0)-Number(l.discount||0),0)-Number(form.discount||0)));const paid=computed(()=>form.payments.reduce((s,p)=>s+Number(p.amount||0),0));const sync=(line:any)=>line.unit_price=list.value?.items.find(i=>i.presentation_id===line.presentation_id)?.price??0;const addLine=()=>{const item=list.value?.items[0];if(item)form.lines.push({sales_order_line_id:null,presentation_id:item.presentation_id,quantity:1,unit_price:item.price,discount:0,price_reason:''})};const addPayment=()=>form.payments.push({financial_account_id:props.accounts[0]?.id??'',amount:0,reference:''});watch(()=>form.customer_profile_id,id=>{const c=props.customers.find(c=>c.id===id);if(c?.default_price_list_id)form.price_list_id=c.default_price_list_id});watch(()=>form.price_list_id,()=>{if(!form.sales_order_id)form.lines.forEach(sync)});watch(()=>form.sales_order_id,id=>{if(!id){form.lines=[];addLine();return}const order=props.orders.find(o=>o.id===id);form.customer_profile_id=order.customer_profile_id??'';form.price_list_id=order.price_list_id;form.lines=order.lines.map((l:any)=>({...l}));});addLine();</script>
<template><form class="grid gap-6" @submit.prevent="form.post('/sales')"><section class="grid gap-4 rounded-xl border bg-card p-5 md:grid-cols-3"><div class="grid gap-2"><label class="text-sm font-medium">Pedido opcional</label><select v-model="form.sales_order_id" class="h-9 rounded-md border bg-transparent px-3 text-sm"><option value="">Venta directa</option><option v-for="o in orders" :key="o.id" :value="o.id">{{o.document_number}}</option></select></div><div class="grid gap-2"><label class="text-sm font-medium">Cliente</label><select v-model="form.customer_profile_id" class="h-9 rounded-md border bg-transparent px-3 text-sm"><option value="">Consumidor final</option><option v-for="c in customers" :key="c.id" :value="c.id">{{c.name}}</option></select></div><div class="grid gap-2"><label class="text-sm font-medium">Lista</label><select v-model="form.price_list_id" :disabled="!!form.sales_order_id" class="h-9 rounded-md border bg-transparent px-3 text-sm"><option v-for="l in priceLists" :key="l.id" :value="l.id">{{l.name}}</option></select></div><div class="grid gap-2"><label class="text-sm font-medium">Fecha</label><Input v-model="form.sold_at" type="datetime-local"/></div><div class="grid gap-2"><label class="text-sm font-medium">Vencimiento si queda crédito</label><Input v-model="form.due_at" type="date"/></div><div class="grid gap-2"><label class="text-sm font-medium">Descuento general</label><Input v-model.number="form.discount" type="number" min="0"/></div></section><section class="grid gap-3"><div class="flex justify-between"><h2 class="font-semibold">Productos</h2><Button v-if="!form.sales_order_id" type="button" variant="outline" size="sm" @click="addLine"><Plus/> Producto</Button></div><div v-for="(line,index) in form.lines" :key="index" class="grid items-end gap-3 rounded-lg border p-3 lg:grid-cols-[1fr_8rem_10rem_9rem_1fr_auto]"><div class="grid gap-2"><label class="text-sm">Presentación</label><select v-model="line.presentation_id" :disabled="!!form.sales_order_id" class="h-9 rounded-md border bg-transparent px-3 text-sm" @change="sync(line)"><option v-for="item in list?.items" :key="item.presentation_id" :value="item.presentation_id">{{item.product}}</option></select></div><div class="grid gap-2"><label class="text-sm">Cantidad</label><Input v-model.number="line.quantity" type="number" min="0.000001" step="0.000001"/></div><div class="grid gap-2"><label class="text-sm">Precio</label><Input v-model.number="line.unit_price" :disabled="!!form.sales_order_id" type="number" min="0"/></div><div class="grid gap-2"><label class="text-sm">Descuento</label><Input v-model.number="line.discount" type="number" min="0"/></div><div class="grid gap-2"><label class="text-sm">Motivo precio</label><Input v-model="line.price_reason" :disabled="!!form.sales_order_id"/></div><Button v-if="!form.sales_order_id" type="button" variant="ghost" size="icon" :disabled="form.lines.length===1" @click="form.lines.splice(index,1)"><Trash2/></Button></div></section><section class="grid gap-3"><div class="flex justify-between"><div><h2 class="font-semibold">Pagos iniciales</h2><p class="text-xs text-muted-foreground">El saldo restante se convierte en cartera; el pedido aplica primero su anticipo.</p></div><Button type="button" variant="outline" size="sm" @click="addPayment"><Plus/> Medio de pago</Button></div><div v-for="(payment,index) in form.payments" :key="index" class="grid items-end gap-3 rounded-lg border p-3 md:grid-cols-[1fr_12rem_1fr_auto]"><select v-model="payment.financial_account_id" class="h-9 rounded-md border bg-transparent px-3 text-sm"><option v-for="a in accounts" :key="a.id" :value="a.id">{{a.name}}</option></select><Input v-model.number="payment.amount" type="number" min="1" placeholder="Valor"/><Input v-model="payment.reference" placeholder="Referencia"/><Button type="button" variant="ghost" size="icon" @click="form.payments.splice(index,1)"><Trash2/></Button></div></section><div class="rounded-lg bg-muted/40 p-4 text-right"><p>Total: <strong>${{total.toLocaleString('es-CO')}}</strong></p><p>Pagos planeados: <strong>${{paid.toLocaleString('es-CO')}}</strong></p><p>Saldo antes de anticipos: <strong>${{Math.max(0,total-paid).toLocaleString('es-CO')}}</strong></p></div><p v-if="Object.keys(form.errors).length" class="text-sm text-destructive">{{Object.values(form.errors)[0]}}</p><div class="flex justify-end gap-2"><Button variant="outline" as-child><Link href="/sales">Cancelar</Link></Button><Button type="submit" :disabled="form.processing||!form.lines.length">Revisar venta</Button></div></form></template>
